      for (let y = y0; y < y1; y += 0.42) { const xo = Math.sin((y - y0) / (y1 - y0) * 3.14) * 0.15, j = P.r(-0.05, 0.05); c.beginPath(); c.rect(q(BX + 0.15 + xo + j), q(y), q(1.7), q(0.34)); c.fillStyle = P.pat(c, 'planks', { tile: 2.5 }); c.fill(); c.fillStyle = P.formShade(c, q(BX), q(y), q(BX + 2), q(y + 0.34)); c.fill(); P.inkStroke(c, 0.8); }
