    const veg = []; for (let y = gy + 0.35; y < gy + 2; y += 0.5) for (let x = gx + 0.3; x < gx + 3.8; x += 0.35) veg.push([x + P.r(-0.05, 0.05), y]); P.dots(veg, '#4f7a2a', 0.11, true);
    P.fence(gx - 0.2, gy - 0.2, gx + 4.2, gy - 0.2); P.fence(gx - 0.2, gy + 2.4, gx + 4.2, gy + 2.4); P.fence(gx - 0.2, gy - 0.2, gx - 0.2, gy + 2.4);
