    P.sprite('td2_cart', CX - C * 0.3, CY + R * 0.05, 1.9, { h: 0.9, z: 40, rot: 1.3 }); P.put('td2_hay', CX - C * 0.3 + 0.3, CY + R * 0.05 + 1.9);
    for (const [dx, dy] of [[1.6, -2.4], [2.3, -2.0], [-2.2, 2.6]]) P.put(rnd() < 0.5 ? 'barrel' : 'crate', CX + dx, CY + dy);
